def expand_tabs(text, width):
    out = []
    col = 0
    for ch in text:
        if ch == '\t':
            n = width - col % width
            out.append(' ' * n)
            col += n
        else:
            out.append(ch)
            col = 0 if ch == '\n' else col + 1
    return ''.join(out)

