def edit_with_undo(operations):
    text = ''
    history = []
    for operation, value in operations:
        if operation == 'undo':
            if history: text = history.pop()
        else:
            history.append(text)
            if operation == 'append': text += value
            elif value: text = text[:-value]
    return text

