def shell_words(text):
    out = []
    word = []
    quoted = False
    active = False
    for ch in text:
        if ch == '"':
            quoted = not quoted
            active = True
        elif ch.isspace() and not quoted:
            if active: out.append(''.join(word))
            word = []
            active = False
        else:
            word.append(ch)
            active = True
    if active: out.append(''.join(word))
    return out

